        days = person["effective_attendance_days"]
        if days >= REST_REQUIRED_THRESHOLD_DAYS:
            lines.append(f"{name}（已考勤{days}天）")
    return lines


def _format_report_path_lines(report_paths: Mapping[str, Any] | None) -> list[str]:
